SHOW work_mem;
SHOW shared_buffers;
SELECT current_setting('max_connections');

SELECT sourcefile, sourceline, name, setting, applied, error
  FROM pg_file_settings
 WHERE name = 'log_min_duration_statement';

SELECT pg_reload_conf();

-- in a new session:
SHOW max_connections;
SELECT name, setting, pending_restart
  FROM pg_settings
 WHERE pending_restart;

CREATE DATABASE shop;
CREATE ROLE report_user LOGIN PASSWORD 'change-me';

ALTER DATABASE shop SET statement_timeout = '30s';
ALTER ROLE report_user SET work_mem = '128MB';
ALTER ROLE report_user IN DATABASE shop SET statement_timeout = '2min';

SET work_mem = '64MB';
SHOW work_mem;
RESET work_mem;

BEGIN;
SET LOCAL statement_timeout = '5s';
SHOW statement_timeout;
COMMIT;
SHOW statement_timeout;

